import zipfile


def uncompress(zip_file, dest_dir):
    """
    This function is used to unzip the zip file and save the extrated files into dest_dir given as an argument.
    Args:
        zip_file: Source file
        dest_dir: Destination directory, in which the extracted files are saved.

    Returns:

    """
    zip_ref = zipfile.ZipFile(zip_file, 'r')
    if len(zip_ref.namelist()) == 0:
        raise Exception("Zip file {} is empty".format(zip_file))
    zip_ref.extractall(dest_dir)
    zip_ref.close()
